import assert from "node:assert/strict"
import { spawnSync } from "node:child_process"
import * as fs from "node:fs/promises"
import * as os from "node:os"
import * as path from "node:path"
const root = path.resolve(process.argv[2] ?? "")
const taskId = process.argv[3]
const requestedChildTimeoutMs = process.argv[4] === undefined ? 110000 : Number(process.argv[4])
assert.ok(Number.isSafeInteger(requestedChildTimeoutMs) && requestedChildTimeoutMs > 0 && requestedChildTimeoutMs <= 110000, "invalid verifier child timeout")
const files = [{"path":"src/cloud/__tests__/docker-provider.test.ts","source":"/**\n * Integration tests for src/cloud/docker-provider.ts — DockerSessionProvider\n * against a REAL local Docker daemon (when available).\n *\n * What is proven (docs/multi-tenant-hosting-design.md §5.2):\n *   1. The full 5-method CloudProvider lifecycle (spawn → waitReady →\n *      runHarness → collectResults → teardown) with real `docker` calls,\n *      including the resource limits applied at spawn (docker inspect shows\n *      NanoCpus / Memory / PidsLimit).\n *   2. Teardown actually removes what spawn created: containers are LISTED\n *      before/after (docker ps -a), not just the exit code trusted.\n *   3. THE isolation proof: two concurrent sessions cannot see or affect each\n *      other — one session's workspace-private file is unreadable from the\n *      other, and a CPU-burning session does not starve its sibling\n *      (per-session cgroup caps).\n *\n * Skip policy (matching the plan's requirement to not fail the whole suite\n * over an environment gap): when `docker` is not installed or the daemon is\n * not reachable, the suite prints a clear SKIP message and exits 0. When the\n * daemon IS available the tests run for real — they are never silently\n * passed without running.\n *\n * Plain assert-based script (no test framework), run via `npm test` →\n * `tsx src/cloud/__tests__/docker-provider.test.ts`.\n */\n\nimport assert from \"node:assert/strict\"\nimport { spawnSync } from \"node:child_process\"\nimport * as fs from \"node:fs\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\n\nimport { DockerSessionProvider } from \"../docker-provider.js\"\nimport type { CloudSessionRequest, CommandResult, SessionHandle } from \"../provider.js\"\n\n// ─── Docker availability probe ───────────────────────────────────────────────\n\nfunction dockerAvailable(): { ok: boolean; reason?: string } {\n\tconst which = spawnSync(\"sh\", [\"-c\", \"command -v docker\"], { encoding: \"utf-8\" })\n\tif (which.status !== 0) {\n\t\treturn { ok: false, reason: \"docker CLI not found on PATH\" }\n\t}\n\tconst ping = spawnSync(\"docker\", [\"version\", \"--format\", \"{{.Server.Version}}\"], {\n\t\tencoding: \"utf-8\",\n\t\ttimeout: 15_000,\n\t})\n\tif (ping.status !== 0) {\n\t\treturn { ok: false, reason: `docker daemon not reachable: ${ping.stderr || \"no server version\"}` }\n\t}\n\treturn { ok: true, reason: `server ${ping.stdout.trim()}` }\n}\n\nfunction sh(cmd: string): CommandResult {\n\tconst res = spawnSync(\"sh\", [\"-c\", cmd], { encoding: \"utf-8\", maxBuffer: 64 * 1024 * 1024 })\n\treturn { exitCode: res.status ?? 1, output: `${res.stdout ?? \"\"}${res.stderr ?? \"\"}`.trim() }\n}\n\n/** Filter docker ps -a by name prefix; returns container NAMES. */\nfunction listContainers(prefix: string): string[] {\n\tconst res = sh(`docker ps -a --format '{{.Names}}'`)\n\tif (res.exitCode !== 0) {\n\t\treturn []\n\t}\n\treturn res.output.split(/\\r?\\n/).map((l) => l.trim()).filter((l) => l.startsWith(prefix))\n}\n\n// ─── Fixture helpers ─────────────────────────────────────────────────────────\n\nfunction tmpRepo(): string {\n\treturn fs.mkdtempSync(path.join(os.tmpdir(), \"headlesscode-docker-repo-\"))\n}\n\nfunction request(repo: string, name = \"w1\"): CloudSessionRequest {\n\treturn {\n\t\trepo,\n\t\tissue: { number: 27, title: \"Fix the bug\", body: \"make it work\" },\n\t\tworktreeSpec: { name, issues: [27], taskFile: `${name}-issue27.md` },\n\t\tenv: { ORCHESTRATOR_MODE: \"code\" },\n\t}\n}\n\n/** A minimal session command that writes completion markers like run-worker.sh does. */\nfunction harnessCmd(exitCode: number): string {\n\t// run-worker.sh writes markers into the WORKTREE path (./.worktrees/<name>/)\n\t// — the workspace mount is the repo root, so the in-container path is\n\t// /workspace/.worktrees/<name>/ (same bytes the host sees at <repo>/.worktrees/<name>/).\n\t// The .worktrees dir is created by the spawner on the host; here the\n\t// container creates it (the workspace bind mount makes it visible to both).\n\t// harness.log is what collectResults tails for its summary.\n\treturn `mkdir -p /workspace/.worktrees/w1 && printf '%s' '${exitCode}' > /workspace/.worktrees/w1/.harness.exit && mkdir -p /workspace/.worktrees/w1/.harness.done && echo \"harness done (exit ${exitCode})\" | tee /workspace/.worktrees/w1/harness.log && exit ${exitCode}`\n}\n\n// ─── Tests ──────────────────────────────────────────────────────────────────\n\n/** Full 5-method lifecycle against the real daemon; asserts limits applied + teardown enumerates removal. */\nasync function testLifecycleAndTeardown(provider: DockerSessionProvider, image: string): Promise<void> {\n\tconst repo = tmpRepo()\n\ttry {\n\t\tconst prefix = \"hcls-test-lifecycle\"\n\t\tconst before = listContainers(prefix)\n\n\t\tconst handle = await provider.spawnWorktreeSession(request(repo))\n\t\tassert.equal(handle.provider, \"docker\")\n\t\tassert.ok(handle.id, \"handle has an id\")\n\t\tassert.ok(handle.containerId, \"handle carries the container id\")\n\n\t\t// Container exists after spawn, with the resource limits applied.\n\t\tconst afterSpawn = listContainers(prefix)\n\t\tassert.ok(afterSpawn.length > before.length, \"container created by spawn\")\n\t\tassert.ok(afterSpawn.includes(`${prefix}-w1`), `container ${prefix}-w1 listed after spawn`)\n\n\t\tconst inspect = sh(`docker inspect ${handle.containerId}`).output\n\t\tconst parsed = JSON.parse(inspect) as Array<{\n\t\t\tHostConfig: { NanoCpus?: number; Memory?: number; PidsLimit?: number }\n\t\t\t// .Image is the resolved sha256 id; .Config.Image is the tag used.\n\t\t\tConfig: { Image: string }\n\t\t}>\n\t\tconst hostCfg = parsed[0].HostConfig\n\t\tassert.ok((hostCfg.NanoCpus ?? 0) > 0, \"CPU limit applied (NanoCpus set)\")\n\t\tassert.ok((hostCfg.Memory ?? 0) > 0, \"memory limit applied (Memory set)\")\n\t\tassert.ok((hostCfg.PidsLimit ?? 0) > 0, \"pids limit applied (PidsLimit set)\")\n\t\tassert.ok(parsed[0].Config.Image.includes(image), `container uses the requested image (${image})`)\n\n\t\tawait provider.waitReady(handle)\n\t\t// waitReady resolved — the container is actually Running (docker inspect Running=true).\n\n\t\t// runHarness executes INSIDE the container and writes workspace markers.\n\t\tconst ran = await provider.runHarness(handle, harnessCmd(0))\n\t\tassert.equal(ran.exitCode, 0, `harness exit 0: ${ran.output}`)\n\t\tassert.match(ran.output, /harness done/, \"harness output returned from inside the container\")\n\n\t\tconst results = await provider.collectResults(handle)\n\t\tassert.equal(results.exitCode, 0)\n\t\tassert.equal(results.done, true)\n\t\tassert.match(String(results.summary), /harness done/)\n\n\t\t// teardown must ACTUALLY remove the container — enumerate, don't trust exit codes.\n\t\tawait provider.teardown(handle)\n\t\tconst afterTeardown = listContainers(prefix)\n\t\tassert.ok(!afterTeardown.includes(`${prefix}-w1`), `container ${prefix}-w1 removed by teardown`)\n\t\tassert.equal(afterTeardown.length, before.length, \"no containers leaked by the lifecycle\")\n\t} finally {\n\t\tsh(`docker rm -f $(docker ps -aq --filter name=hcls-test-lifecycle) 2>/dev/null || true`)\n\t\tfs.rmSync(repo, { recursive: true, force: true })\n\t}\n}\n\n/** Run a harness command inside a spawned session (helper for the isolation test). */\nasync function runInSession(provider: DockerSessionProvider, handle: SessionHandle, cmd: string): Promise<CommandResult> {\n\tawait provider.waitReady(handle)\n\treturn provider.runHarness(handle, cmd)\n}\n\n/**\n * THE isolation proof (docs/multi-tenant-hosting-design.md §5.2): two\n * concurrent sessions — one cannot read the other's workspace-private file,\n * and one's CPU burn does not starve the other (cgroup caps).\n */\nasync function testIsolationBetweenConcurrentSessions(provider: DockerSessionProvider): Promise<void> {\n\tconst repoA = tmpRepo()\n\tconst repoB = tmpRepo()\n\ttry {\n\t\t// Pre-clean containers from a previous run of THIS test (e.g. a crashed\n\t\t// or interrupted suite, or another worktree's npm test running in\n\t\t// parallel). Without this, spawnWorktreeSession's pre-clean races with\n\t\t// the daemon's own state and the second run fails with a stale-name\n\t\t// conflict or a \"No such container\" mid-test.\n\t\tsh(`docker rm -f $(docker ps -aq --filter name=hcls-test-iso) 2>/dev/null || true`)\n\t\tconst handleA = await provider.spawnWorktreeSession(request(repoA, \"iso-a\"))\n\t\tconst handleB = await provider.spawnWorktreeSession(request(repoB, \"iso-b\"))\n\t\ttry {\n\t\t\t// Both sessions run concurrently (both spawned, both waited).\n\t\t\tawait provider.waitReady(handleA)\n\t\t\tawait provider.waitReady(handleB)\n\n\t\t\t// 1. Filesystem/visibility isolation: session A writes a\n\t\t\t//    tenant-private file; session B must NOT be able to read it.\n\t\t\tconst writeA = await provider.runHarness(\n\t\t\t\thandleA,\n\t\t\t\t`mkdir -p /workspace/tenant-private && printf 'secret-of-A' > /workspace/tenant-private/a-only.txt && echo wrote`,\n\t\t\t)\n\t\t\tassert.equal(writeA.exitCode, 0, `A wrote its private file: ${writeA.output}`)\n\n\t\t\tconst readFromB = await provider.runHarness(\n\t\t\t\thandleB,\n\t\t\t\t`cat /workspace/tenant-private/a-only.txt 2>&1; test -e /workspace/tenant-private/a-only.txt; echo \"visible_from_B=$?\"`,\n\t\t\t)\n\t\t\tassert.equal(readFromB.exitCode, 0, \"B's check command itself succeeded\")\n\t\t\t// B sees no such file — A's workspace mount is private to A.\n\t\t\tassert.match(readFromB.output, /No such file/, `B cannot see A's file: ${readFromB.output}`)\n\t\t\tassert.match(readFromB.output, /visible_from_B=1/, `B's own view is clean: ${readFromB.output}`)\n\n\t\t\t// 2. Resource isolation: B burns CPU while A runs a normal command.\n\t\t\t//    B is capped by its own --cpus limit, so it cannot starve A.\n\t\t\tconst burnPromise = provider.runHarness(\n\t\t\t\thandleB,\n\t\t\t\t`( for i in $(seq 1 200000); do : ; done; echo \"burn done\" ) &\n\t\t\t\t echo \"burn started\"; sleep 8`,\n\t\t\t)\n\t\t\tawait new Promise((resolve) => setTimeout(resolve, 1000)) // let B's burn ramp up\n\t\t\tconst startA = Date.now()\n\t\t\tconst readFromA = await provider.runHarness(handleA, `echo \"A alive\"; printf 'secret-of-A' > /workspace/tenant-private/a-only.txt`)\n\t\t\tconst aLatency = Date.now() - startA\n\t\t\tawait burnPromise\n\n\t\t\tassert.equal(readFromA.exitCode, 0, `A completes normally while B burns CPU: ${readFromA.output}`)\n\t\t\tassert.match(readFromA.output, /A alive/)\n\t\t\tassert.ok(aLatency < 10_000, `A not starved by B's burn (latency ${aLatency}ms)`)\n\t\t} finally {\n\t\t\tawait provider.teardown(handleA)\n\t\t\tawait provider.teardown(handleB)\n\t\t}\n\n\t\t// Teardown enumerated: no iso-* containers remain.\n\t\tconst remaining = listContainers(\"hcls-test-iso\")\n\t\tassert.ok(!remaining.includes(\"hcls-test-iso-iso-a\"), \"iso-a container removed\")\n\t\tassert.ok(!remaining.includes(\"hcls-test-iso-iso-b\"), \"iso-b container removed\")\n\t} finally {\n\t\tsh(`docker rm -f $(docker ps -aq --filter name=hcls-test-iso) 2>/dev/null || true`)\n\t\tfs.rmSync(repoA, { recursive: true, force: true })\n\t\tfs.rmSync(repoB, { recursive: true, force: true })\n\t}\n}\n\n/** Unit-level: no daemon needed — injected run/isReady/listContainers fakes drive the lifecycle. */\nasync function testUnitWithInjectedFakes(): Promise<void> {\n\tconst calls: string[] = []\n\tconst fakeRun = (command: string): CommandResult => {\n\t\tcalls.push(command)\n\t\t// Spawn = pre-clean + docker create (newline-joined); then a separate\n\t\t// docker start. The create output is the container id.\n\t\tif (command.includes(\"docker create\")) {\n\t\t\treturn { exitCode: 0, output: \"fef445205b9c6f3389bafcbc818601b58d89d304202a807c8fcc416342bf0fac\" }\n\t\t}\n\t\tif (command.startsWith(\"docker start\")) {\n\t\t\treturn { exitCode: 0, output: \"started\" }\n\t\t}\n\t\tif (command.startsWith(\"docker inspect\")) {\n\t\t\treturn { exitCode: 0, output: JSON.stringify([{ State: { Running: true } }]) }\n\t\t}\n\t\tif (command.startsWith(\"docker exec\")) {\n\t\t\treturn { exitCode: 0, output: \"ran: \" + command }\n\t\t}\n\t\tif (command.startsWith(\"docker rm -f\")) {\n\t\t\treturn { exitCode: 0, output: \"removed\" }\n\t\t}\n\t\treturn { exitCode: 0, output: \"\" }\n\t}\n\tconst provider = new DockerSessionProvider({\n\t\trun: fakeRun,\n\t\tisReady: () => true,\n\t\tlistContainers: () => [],\n\t})\n\n\tconst repo = tmpRepo()\n\ttry {\n\t\tconst handle = await provider.spawnWorktreeSession(request(repo, \"w-fake\"))\n\t\tassert.ok(calls.some((c) => c.includes(\"docker create\")), \"spawn issues docker create\")\n\t\tconst spawnCall = calls.find((c) => c.includes(\"docker create\"))!\n\t\tassert.match(spawnCall, /--cpus \\d+/, \"CPU limit in the run command\")\n\t\tassert.match(spawnCall, /--memory \\d+m/, \"memory limit in the run command\")\n\t\tassert.match(spawnCall, /--pids-limit \\d+/, \"pids limit in the run command\")\n\t\tassert.match(spawnCall, /--user \\d+:\\d+/, \"container runs as a non-root uid:gid\")\n\t\tassert.match(spawnCall, /--read-only/, \"read-only rootfs\")\n\t\tassert.match(spawnCall, /-v .*:\\/workspace/, \"workspace mount\")\n\t\tassert.match(spawnCall, /-v .*:\\/harness:ro/, \"harness mount read-only\")\n\n\t\tawait provider.waitReady(handle)\n\t\tconst ran = await provider.runHarness(handle, \"echo hi\")\n\t\tassert.equal(ran.exitCode, 0)\n\t\tassert.match(ran.output, /ran: docker exec/)\n\t\tawait provider.teardown(handle)\n\t\tassert.ok(calls.some((c) => c.startsWith(\"docker rm -f\")), \"teardown removes the container\")\n\t} finally {\n\t\tfs.rmSync(repo, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"DockerSessionProvider unit: injected fakes drive spawn/wait/run/teardown command shapes\", testUnitWithInjectedFakes],\n]\n\nlet dockerNote = \"\"\nconst probe = dockerAvailable()\nif (probe.ok) {\n\tdockerNote = `real Docker daemon: ${probe.reason}`\n\ttests.push(\n\t\t[\"DockerSessionProvider lifecycle + teardown enumeration (real daemon)\", () => {\n\t\t\tconst provider = new DockerSessionProvider({ namePrefix: \"hcls-test-lifecycle\" })\n\t\t\treturn testLifecycleAndTeardown(provider, \"node:22-bookworm-slim\")\n\t\t}],\n\t\t[\"Isolation proof: two concurrent sessions cannot see or starve each other (real daemon)\", () => {\n\t\t\tconst provider = new DockerSessionProvider({ namePrefix: \"hcls-test-iso\" })\n\t\t\treturn testIsolationBetweenConcurrentSessions(provider)\n\t\t}],\n\t)\n} else {\n\tdockerNote = `SKIP real-daemon tests: ${probe.reason}`\n}\n\nasync function main(): Promise<void> {\n\tconsole.log(`  note: ${dockerNote}`)\n\tlet failed = 0\n\tlet skipped = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t}\n\t}\n\tif (!probe.ok) {\n\t\tskipped = 2\n\t\tconsole.log(`  SKIP ${skipped} real-daemon test(s) — ${probe.reason}`)\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} docker-provider tests passed (${skipped} skipped: no Docker daemon)`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"},{"path":"src/permissions/__tests__/commands.test.ts","source":"/**\n * Unit tests for command allow/deny + dangerous-substitution decisions\n * (src/permissions/commands.ts). Plain assert-based script (no test framework,\n * no network), run via `npm test` -> `tsx src/permissions/__tests__/commands.test.ts`.\n *\n * Covers: dangerous substitutions always refused regardless of config; deny\n * wins over allow (longest-prefix-match, ties to deny); default-ALLOW when the\n * allow-list is unset; compound commands (&&/;/|) checked per sub-command; and\n * the faithful `getCommandDecision` port (upstream decision vocabulary).\n */\n\nimport assert from \"node:assert/strict\"\nimport * as fs from \"node:fs/promises\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\n\nimport {\n\tcheckCommand,\n\tcheckRedirectEscape,\n\tcontainsDangerousSubstitution,\n\tdecideCommand,\n\tdescribeRedirect,\n\tfindLongestPrefixMatch,\n\tgetCommandDecision,\n\tisOutsideWorkspace,\n\tparseCommand,\n\tredirectTargets,\n\tresolveRedirectTarget,\n} from \"../commands.js\"\n\n// ─── (a) dangerous substitutions are always refused, regardless of config ───\n\nasync function testDangerousSubstitutionsAlwaysDenied(): Promise<void> {\n\tconst dangerous = [\n\t\t'echo \"${var@P}\"', // prompt-string expansion\n\t\t'echo \"${var@Q}\"', // quote removal\n\t\t'echo \"${x@E}\"', // escape expansion\n\t\t'echo \"${!var}\"', // indirect expansion\n\t\t\"cat <<<$(id)\", // here-string with command substitution\n\t\t\"cat <<<`id`\", // here-string with backtick substitution\n\t\t\"=(whoami)\", // zsh process substitution that executes a command\n\t\t\"rm -rf *(e:whoami:)\", // zsh glob qualifier with code execution\n\t\t'echo \"${x=\\\\140id\\\\140}\"', // assignment with escape-embedded backtick\n\t]\n\tfor (const cmd of dangerous) {\n\t\tassert.equal(containsDangerousSubstitution(cmd), true, `containsDangerousSubstitution(${cmd}) should be true`)\n\t\t// Refused even with an allow-list that would otherwise permit the prefix…\n\t\tassert.equal(decideCommand(cmd, [\"echo\", \"cat\", \"rm\"], []), \"deny\", `decideCommand(${cmd}, allow) should deny`)\n\t\t// …and refused even with ZERO config (default-allow still never covers these).\n\t\tassert.equal(decideCommand(cmd, [], []), \"deny\", `decideCommand(${cmd}, no config) should deny`)\n\t\tconst refusal = checkCommand(cmd, [\"echo\", \"cat\", \"rm\"], [])\n\t\tassert.ok(refusal !== null && refusal.kind === \"dangerous\", `checkCommand(${cmd}) should be kind=dangerous`)\n\t}\n\n\t// Control: ordinary commands are NOT flagged.\n\tassert.equal(containsDangerousSubstitution(\"echo hi\"), false)\n\tassert.equal(containsDangerousSubstitution(\"git status\"), false)\n}\n\n// ─── (b) deny-list match refused even when also allow-listed ────────────────\n\nasync function testDenyWinsOverAllow(): Promise<void> {\n\t// More specific deny beats a shorter allow (longest-prefix-match).\n\tassert.equal(decideCommand(\"git push origin\", [\"git\"], [\"git push\"]), \"deny\")\n\t// More specific allow beats a shorter deny.\n\tassert.equal(decideCommand(\"git push --dry-run\", [\"git push --dry-run\"], [\"git push\"]), \"allow\")\n\t// Tie (equal-length matches) goes to deny.\n\tassert.equal(decideCommand(\"rm x\", [\"rm\"], [\"rm\"]), \"deny\")\n\t// Deny in a compound chain blocks the whole command.\n\tassert.equal(decideCommand(\"echo hi && rm -rf /\", [\"echo\"], [\"rm\"]), \"deny\")\n\tassert.equal(decideCommand(\"echo hi && rm -rf /\", [\"rm\"], [\"rm\"]), \"deny\")\n\n\tconst refusal = checkCommand(\"git push origin\", [\"git\"], [\"git push\"])\n\tassert.ok(refusal !== null && refusal.kind === \"denied\", \"checkCommand should report kind=denied\")\n\tassert.equal(refusal.subCommand, \"git push origin\", \"refusal must name the offending sub-command\")\n\tassert.equal(refusal.pattern, \"git push\", \"refusal must name the matched deny pattern\")\n}\n\n// ─── (c) allow-list-only commands pass; default-ALLOW when list unset ───────\n\nasync function testAllowListSemantics(): Promise<void> {\n\t// Explicit allow-list: matching commands pass.\n\tassert.equal(decideCommand(\"echo hi\", [\"echo\"], []), \"allow\")\n\tassert.equal(decideCommand(\"git status\", [\"git\"], []), \"allow\")\n\t// Allow-list configured but a command doesn't match it: denied (a headless\n\t// harness has no human to ask, so \"ask_user\" is refused).\n\tassert.equal(decideCommand(\"rm x\", [\"git\"], []), \"deny\")\n\tconst notAllowed = checkCommand(\"rm x\", [\"git\"], [])\n\tassert.ok(notAllowed !== null && notAllowed.kind === \"not_allowed\", \"non-matching command with allow-list = not_allowed\")\n\n\t// DEFAULT-ALLOW (deliberate, documented decision): empty allow-list means\n\t// \"allow everything except the deny-list\" — preserves pre-permissions\n\t// behavior for sessions that configure nothing.\n\tassert.equal(decideCommand(\"git status\", [], []), \"allow\", \"empty allow + empty deny = default-allow\")\n\tassert.equal(decideCommand(\"echo hi\", [], []), \"allow\")\n\t// ...but the always-on central-store protection still refuses recursive\n\t// deletes targeting the store or a PARENT of it, even with zero config —\n\t// `rm -rf /` (a parent of everything) and `rm -rf ~` are caught by it, not\n\t// by the (empty) deny-list. Full matrix in store-protection.test.ts.\n\tassert.equal(decideCommand(\"rm -rf /\", [], []), \"deny\", \"store protection refuses rm -rf / even with zero config\")\n\tassert.equal(decideCommand(\"rm -rf /opt/scratch-x\", [], []), \"allow\", \"non-store targets still default-allow\")\n\t// deniedCommands ALWAYS applies, even when the empty allow-list would\n\t// otherwise allow everything else.\n\tassert.equal(decideCommand(\"rm -rf /opt/scratch-x\", [], [\"rm\"]), \"deny\")\n\tassert.equal(decideCommand(\"echo hi\", [], [\"rm\"]), \"allow\")\n}\n\n// ─── (d) compound commands checked per sub-command, not as one opaque string ─\n\nasync function testCompoundCommandsCheckedPerSubCommand(): Promise<void> {\n\t// `echo hi` is allowed but the chained `rm -rf /` is not — must be caught.\n\tassert.equal(decideCommand(\"echo hi && rm -rf /\", [\"echo\"], []), \"deny\")\n\tassert.equal(decideCommand(\"echo hi; rm -rf /\", [\"echo\"], []), \"deny\")\n\tassert.equal(decideCommand(\"echo hi || rm -rf /\", [\"echo\"], []), \"deny\")\n\tassert.equal(decideCommand(\"ls | rm -rf /\", [\"ls\"], []), \"deny\")\n\tassert.equal(decideCommand(\"echo hi & rm -rf /\", [\"echo\"], []), \"deny\")\n\t// When every sub-command is allowed, the chain passes (target is a\n\t// non-store path — the store protection only refuses store targets).\n\tassert.equal(decideCommand(\"echo hi && rm -rf /opt/scratch-x\", [\"echo\", \"rm\"], []), \"allow\")\n\t// Quoted operators are NOT separators — single sub-command.\n\tassert.equal(decideCommand('echo \"a && b\"', [\"echo\"], []), \"allow\")\n\n\tassert.deepEqual(parseCommand(\"echo hi && rm -rf /\").commands, [\"echo hi\", \"rm -rf /\"])\n\tassert.deepEqual(parseCommand(\"echo hi; rm -rf /\").commands, [\"echo hi\", \"rm -rf /\"])\n\tassert.deepEqual(parseCommand(\"echo hi | head -1\").commands, [\"echo hi\", \"head -1\"])\n\tassert.deepEqual(parseCommand('echo \"a && b\"').commands, ['echo \"a && b\"'])\n\t// Subshell contents are promoted to their own sub-command (reference behavior).\n\tassert.deepEqual(parseCommand(\"echo $(rm -rf /)\").commands, [\"echo\", \"rm -rf /\"])\n\n\t// Malformed commands (unterminated quote) are refused, never auto-run.\n\tconst malformed = parseCommand('echo \"unterminated')\n\tassert.ok(malformed.parseError !== null, \"unterminated quote must produce a parseError\")\n\tassert.equal(decideCommand('echo \"unterminated', [\"echo\"], []), \"deny\")\n\tconst malformedRefusal = checkCommand('echo \"unterminated', [\"echo\"], [])\n\tassert.ok(malformedRefusal !== null && malformedRefusal.kind === \"malformed\", \"malformed = kind malformed\")\n}\n\n// ─── upstream getCommandDecision port parity ────────────────────────────────\n\nasync function testGetCommandDecisionPortParity(): Promise<void> {\n\tassert.equal(getCommandDecision(\"\", [], []), \"auto_approve\")\n\tassert.equal(getCommandDecision(\"git status\", [\"git\"], []), \"auto_approve\")\n\tassert.equal(getCommandDecision('echo \"${var@P}\"', [\"echo\"], []), \"ask_user\") // never auto-approved\n\tassert.equal(getCommandDecision(\"git push origin\", [\"git\"], [\"git push\"]), \"auto_deny\")\n\tassert.equal(getCommandDecision(\"git status && rm file\", [\"git\"], [\"rm\"]), \"auto_deny\")\n\tassert.equal(getCommandDecision(\"unknown command\", [\"git\"], [\"rm\"]), \"ask_user\")\n\tassert.equal(getCommandDecision('echo \"unterminated', [\"echo\"], []), \"malformed_command\")\n}\n\n// ─── findLongestPrefixMatch port parity ─────────────────────────────────────\n\nasync function testFindLongestPrefixMatch(): Promise<void> {\n\tassert.equal(findLongestPrefixMatch(\"git push origin\", [\"git\", \"git push\"]), \"git push\")\n\tassert.equal(findLongestPrefixMatch(\"npm install\", [\"*\", \"npm\"]), \"npm\", \"specific match beats wildcard\")\n\tassert.equal(findLongestPrefixMatch(\"unknown command\", [\"git\", \"npm\"]), null)\n\tassert.equal(findLongestPrefixMatch(\"rm -rf /\", [\"rm\"]), \"rm\")\n\tassert.equal(findLongestPrefixMatch(\"\", [\"git\"]), null)\n}\n\n// ─── (e) redirect-escape guard (issue #122): >/>>/2>/&> outside the workspace ─\n\nasync function testRedirectEscapeAlwaysDenied(): Promise<void> {\n\tconst ws = await fs.mkdtemp(path.join(os.tmpdir(), \"hc-commands-redir-\"))\n\ttry {\n\t\tconst outside = path.join(os.tmpdir(), `hc-commands-outside-${process.pid}`)\n\t\tawait fs.rm(outside, { recursive: true, force: true })\n\t\ttry {\n\t\t\tconst escaping = [\n\t\t\t\t`cat > /tmp/foo.md`,\n\t\t\t\t`cat >> /tmp/foo.md`,\n\t\t\t\t`echo hi 2> /tmp/err.log`,\n\t\t\t\t`echo hi 2>> /tmp/err.log`,\n\t\t\t\t`echo hi &> /tmp/both.log`,\n\t\t\t\t`echo hi &>> /tmp/both.log`,\n\t\t\t\t`cat >| /tmp/foo.md`,\n\t\t\t\t`echo hi 2>| /tmp/err.log`,\n\t\t\t\t`echo hi > ~/out.txt`,\n\t\t\t\t`echo hi > ${outside}/out.txt`,\n\t\t\t\t`echo hi > $HC_TEST_OUTDIR/x.txt`,\n\t\t\t\t`echo hi > \"${outside}/a b.txt\"`,\n\t\t\t\t`echo hi > '${outside}/single.txt'`,\n\t\t\t\t`cat > /tmp/x && echo ok`, // compound: escaping sub-command blocks the chain\n\t\t\t\t`echo a > /tmp/a.txt; echo b > /tmp/b.txt`,\n\t\t\t]\n\t\t\t// $HC_TEST_OUTDIR resolves through expandEnv like any $VAR — pin it\n\t\t\t// to the temp dir so the escaping case is deterministic.\n\t\t\tconst savedVar = process.env.HC_TEST_OUTDIR\n\t\t\tprocess.env.HC_TEST_OUTDIR = os.tmpdir()\n\t\t\ttry {\n\t\t\t\tfor (const cmd of escaping) {\n\t\t\t\t\t// Refused even with an allow-list that would otherwise permit it…\n\t\t\t\t\tassert.equal(\n\t\t\t\t\t\tdecideCommand(cmd, [\"cat\", \"echo\", \"rm\"], [], { workspaceRoot: ws }),\n\t\t\t\t\t\t\"deny\",\n\t\t\t\t\t\t`decideCommand(${cmd}) with allow-list should deny`,\n\t\t\t\t\t)\n\t\t\t\t\t// …and with ZERO config (default-allow never covers redirect escapes).\n\t\t\t\t\tassert.equal(\n\t\t\t\t\t\tdecideCommand(cmd, [], [], { workspaceRoot: ws }),\n\t\t\t\t\t\t\"deny\",\n\t\t\t\t\t\t`decideCommand(${cmd}) with zero config should deny`,\n\t\t\t\t\t)\n\t\t\t\t\tconst refusal = checkCommand(cmd, [\"cat\", \"echo\", \"rm\"], [], { workspaceRoot: ws })\n\t\t\t\t\tassert.ok(\n\t\t\t\t\t\trefusal !== null && refusal.kind === \"redirect_escape\",\n\t\t\t\t\t\t`checkCommand(${cmd}) should be kind=redirect_escape (got ${refusal?.kind})`,\n\t\t\t\t\t)\n\t\t\t\t\tassert.ok(refusal.redirect !== undefined, \"refusal must carry the offending redirect\")\n\t\t\t\t\tassert.ok(\n\t\t\t\t\t\tisOutsideWorkspace(ws, resolveRedirectTarget(refusal.redirect.word, ws)),\n\t\t\t\t\t\t`refusal.redirect.word (${refusal.redirect.word}) must resolve outside the workspace`,\n\t\t\t\t\t)\n\t\t\t\t}\n\n\t\t\t\t// Redirects that STAY inside the workspace are allowed.\n\t\t\t\tconst allowed = [\n\t\t\t\t\t`cat > out.txt`,\n\t\t\t\t\t`echo hi > ./out.txt`,\n\t\t\t\t\t`echo hi > ${path.join(ws, \"sub\")}/out.txt`,\n\t\t\t\t\t`echo hi >> ${ws}/out.log`,\n\t\t\t\t\t`echo hi 2> ${ws}/err.log`,\n\t\t\t\t\t`cat > \"${ws}/a b.txt\"`,\n\t\t\t\t\t`echo hi > $TMPDIR/x 2>&1`, // 2>&1 is fd duplication, NOT a path redirect\n\t\t\t\t\t`echo hi > out.txt && echo ok > out2.txt`,\n\t\t\t\t]\n\t\t\t\tfor (const cmd of allowed) {\n\t\t\t\t\tassert.equal(\n\t\t\t\t\t\tdecideCommand(cmd, [], [], { workspaceRoot: ws }),\n\t\t\t\t\t\t\"allow\",\n\t\t\t\t\t\t`decideCommand(${cmd}) should allow (target inside the workspace)`,\n\t\t\t\t\t)\n\t\t\t\t}\n\t\t\t} finally {\n\t\t\t\tif (savedVar === undefined) {\n\t\t\t\t\tdelete process.env.HC_TEST_OUTDIR\n\t\t\t\t} else {\n\t\t\t\t\tprocess.env.HC_TEST_OUTDIR = savedVar\n\t\t\t\t}\n\t\t\t}\n\t\t} finally {\n\t\t\tawait fs.rm(outside, { recursive: true, force: true })\n\t\t}\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\nasync function testRedirectTargetParsing(): Promise<void> {\n\tconst ws = await fs.mkdtemp(path.join(os.tmpdir(), \"hc-commands-redir-parse-\"))\n\ttry {\n\t\t// Targets are extracted with quote-stripped words.\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi > /tmp/foo.md`).map((t) => t.word),\n\t\t\t[\"/tmp/foo.md\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi >> /tmp/foo.md`).map((t) => t.word),\n\t\t\t[\"/tmp/foo.md\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi 2> /tmp/err.log`).map((t) => t.word),\n\t\t\t[\"/tmp/err.log\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi 2>> /tmp/err.log`).map((t) => t.word),\n\t\t\t[\"/tmp/err.log\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi &> /tmp/both.log`).map((t) => t.word),\n\t\t\t[\"/tmp/both.log\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo hi &>> /tmp/both.log`).map((t) => t.word),\n\t\t\t[\"/tmp/both.log\"],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`cat > \"${os.tmpdir()}/a b.txt\"`).map((t) => t.word),\n\t\t\t[`${os.tmpdir()}/a b.txt`],\n\t\t)\n\t\tassert.deepEqual(\n\t\t\tredirectTargets(`echo a > /tmp/a.txt; echo b > /tmp/b.txt`).map((t) => t.word),\n\t\t\t[\"/tmp/a.txt\", \"/tmp/b.txt\"],\n\t\t)\n\t\t// Input redirects (<, <<, <<<) and fd duplication (2>&1) carry no OUTPUT path.\n\t\tassert.deepEqual(redirectTargets(`cat < /etc/hostname`), [])\n\t\tassert.deepEqual(redirectTargets(`cat <<EOF\\nhi\\nEOF`), [])\n\t\tassert.deepEqual(redirectTargets(`cat <<< hi`), [])\n\t\tassert.deepEqual(redirectTargets(`echo hi 2>&1`), [])\n\t\tassert.deepEqual(redirectTargets(`echo hi 3>&2`), [])\n\t\t// A redirect with NO target word emits nothing (the shell would error).\n\t\tassert.deepEqual(redirectTargets(`echo hi >`), [])\n\n\t\t// checkRedirectEscape resolves `~` and `$VAR` against the workspace root.\n\t\tassert.notEqual(checkRedirectEscape(`echo hi > ~/x.txt`, ws), null, \"~ escapes the workspace\")\n\t\tassert.notEqual(checkRedirectEscape(`echo hi > $HOME/x.txt`, ws), null, \"$HOME escapes the workspace\")\n\t\tassert.equal(checkRedirectEscape(`echo hi > ./x.txt`, ws), null, \"relative targets stay inside\")\n\t\tassert.equal(checkRedirectEscape(`echo hi > out.txt`, ws), null)\n\t\tassert.equal(checkRedirectEscape(`echo hi > $TMPDIR/x 2>&1`, ws), null, \"fd duplication is not a redirect target\")\n\t\t// Heredoc BODY redirects are still caught (raw scan, pre-parse).\n\t\tassert.notEqual(checkRedirectEscape(`cat <<EOF\\n> /tmp/x\\nEOF`, ws), null, \"heredoc body redirect escapes\")\n\n\t\t// describeRedirect renders an operator + word pair for refusal messages.\n\t\tassert.equal(describeRedirect({ operator: \">\", word: \"/tmp/foo.md\", index: 0 }), \"> /tmp/foo.md\")\n\t\tassert.equal(describeRedirect({ operator: \">>\", word: \"/tmp/foo.md\", index: 0 }), \">>/tmp/foo.md\")\n\t\tassert.equal(describeRedirect({ operator: \"2>\", word: \"/tmp/err.log\", index: 0 }), \"2> /tmp/err.log\")\n\t\tassert.equal(describeRedirect({ operator: \"&>\", word: \"/tmp/both.log\", index: 0 }), \"&>/tmp/both.log\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\nasync function testRedirectEscapeNotOverridableByAllowList(): Promise<void> {\n\tconst ws = await fs.mkdtemp(path.join(os.tmpdir(), \"hc-commands-redir-override-\"))\n\ttry {\n\t\t// An allow-everything config does NOT bypass the redirect-escape guard.\n\t\tconst refusal = checkCommand(`cat > /tmp/foo.md`, [\"*\", \"cat\"], [], { workspaceRoot: ws })\n\t\tassert.ok(refusal !== null && refusal.kind === \"redirect_escape\", \"allow-everything config cannot override the guard\")\n\t\tassert.equal(decideCommand(`cat > /tmp/foo.md`, [\"*\"], [], { workspaceRoot: ws }), \"deny\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"dangerous substitutions always denied regardless of config\", testDangerousSubstitutionsAlwaysDenied],\n\t[\"deny-list match refused even when also allow-listed (longest-prefix-match, tie->deny)\", testDenyWinsOverAllow],\n\t[\"allow-list-only commands pass; default-ALLOW when list unset; deny always applies\", testAllowListSemantics],\n\t[\"compound commands (&&/;||/|/&) checked per sub-command; malformed refused\", testCompoundCommandsCheckedPerSubCommand],\n\t[\"getCommandDecision port matches upstream decision vocabulary\", testGetCommandDecisionPortParity],\n\t[\"findLongestPrefixMatch port matches upstream semantics\", testFindLongestPrefixMatch],\n\t[\"redirect-escape guard (issue #122): >/>>/2>/&> outside the workspace always denied, inside allowed\", testRedirectEscapeAlwaysDenied],\n\t[\"redirect target extraction + resolution + describeRedirect\", testRedirectTargetParsing],\n\t[\"redirect-escape guard is NOT overridable by an allow-everything config\", testRedirectEscapeNotOverridableByAllowList],\n]\n\nasync function main(): Promise<void> {\n\tlet failed = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t}\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} command-permissions tests passed`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"},{"path":"src/tools/__tests__/execute_command.test.ts","source":"/**\n * Unit tests for the execute_command timeout semantics\n * (src/tools/executor.ts's executeCommandHandler).\n *\n * The vendored tool contract (src/vendor/zoo-code/src/core/prompts/tools/\n * native-tools/execute_command.ts) says a command whose `timeout` elapses\n * KEEPS RUNNING in the background and the model gets the output captured so\n * far — it must NOT be killed, and the result must be a normal (non-error)\n * tool result so the loop's consecutive-mistake counter is untouched.\n *\n * Plain assert-based script (no test framework, no network), run via\n * `npm test` -> `tsx src/tools/__tests__/execute_command.test.ts`.\n */\n\nimport assert from \"node:assert/strict\"\nimport * as fs from \"node:fs/promises\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\nimport { setTimeout as sleep } from \"node:timers/promises\"\n\nimport { createHeadlessExecutor, BASH_PATH, MAX_RESULT_CHARS } from \"../executor.js\"\n\nasync function mkTmpWorkspace(prefix: string): Promise<string> {\n\treturn fs.mkdtemp(path.join(os.tmpdir(), prefix))\n}\n\nasync function exists(p: string): Promise<boolean> {\n\ttry {\n\t\tawait fs.access(p)\n\t\treturn true\n\t} catch {\n\t\treturn false\n\t}\n}\n\n/** Poll `process.kill(pid, 0)` until the process is gone (throws) or timeout. */\nasync function waitForProcessExit(pid: number, timeoutMs = 5_000): Promise<void> {\n\tconst deadline = Date.now() + timeoutMs\n\twhile (Date.now() < deadline) {\n\t\ttry {\n\t\t\tprocess.kill(pid, 0)\n\t\t} catch {\n\t\t\treturn // gone\n\t\t}\n\t\tawait sleep(50)\n\t}\n\tthrow new Error(`process ${pid} still alive after ${timeoutMs}ms`)\n}\n\n// ─── (a) command finishes well within its timeout ───────────────────────────\n\nasync function testNormalCompletionWithinTimeout(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-ok-\")\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws)\n\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: \"node -e 'console.log(40 + 2)'\",\n\t\t\ttimeout: 10,\n\t\t})\n\n\t\tassert.equal(result.isError, false, \"a command that finishes must be a normal result\")\n\t\tassert.match(result.content, /42/, \"stdout must be captured\")\n\t\tassert.doesNotMatch(result.content, /timed out/, \"no timeout marker for a fast command\")\n\t\tassert.doesNotMatch(result.content, /^\\[Error\\]/, \"no error prefix for a fast command\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (b) timeout: non-error result, partial output, process keeps running ───\n\nasync function testTimeoutKeepsProcessAliveAndWritesMarker(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-timeout-\")\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst marker = path.join(ws, \"marker.txt\")\n\n\t\t// Prints its own PID immediately, then writes a marker file after a\n\t\t// delay (4s) well past the 1s timeout — if the timeout killed it, the\n\t\t// marker would never appear.\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand:\n\t\t\t\t`node -e 'console.log(\"pid=\" + process.pid); ` +\n\t\t\t\t`setTimeout(() => require(\"fs\").writeFileSync(${JSON.stringify(marker)}, \"done\"), 4000)'`,\n\t\t\ttimeout: 1,\n\t\t})\n\n\t\tassert.equal(result.isError, false, \"a timeout is expected/intentional, NOT an error result\")\n\t\tassert.match(result.content, /timed out after 1s/, \"result must be clearly marked as a timeout\")\n\t\tassert.match(result.content, /still running in the background/, \"must say the process is still running\")\n\t\tassert.match(result.content, /pid=\\d+/, \"partial output captured before the timeout must be returned\")\n\n\t\tconst pid = Number(result.content.match(/pid=(\\d+)/)?.[1])\n\t\tassert.ok(Number.isInteger(pid) && pid > 0, \"could not extract the backgrounded pid from the output\")\n\n\t\t// Immediately after the tool returned (well before the 4s delay): the\n\t\t// process must STILL be alive — the timeout must not have killed it —\n\t\t// and the marker must not be written yet.\n\t\tassert.doesNotThrow(() => process.kill(pid, 0), \"backgrounded process must be alive right after the timeout\")\n\t\tassert.equal(await exists(marker), false, \"marker not written yet — process is still mid-run\")\n\n\t\t// Past the 4s delay the process finished on its own and wrote the file.\n\t\tawait sleep(4_500)\n\t\tassert.equal(await exists(marker), true, \"backgrounded process must keep running past the timeout and write its marker\")\n\t\t// …and it exited normally on its own (no kill needed).\n\t\tawait waitForProcessExit(pid)\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (c) central-store protection (see src/permissions/store-protection.ts) ──\n\nasync function testRecursiveDeleteOfCentralStoreRefusedBeforeSpawn(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-store-ws-\")\n\tconst storeBase = await mkTmpWorkspace(\"hc-ec-store-data-\")\n\tconst storeRoot = path.join(storeBase, \"central-store\")\n\tawait fs.mkdir(storeRoot, { recursive: true })\n\tconst marker = path.join(storeRoot, \"marker.txt\")\n\tawait fs.writeFile(marker, \"keep-me\")\n\tconst savedDataDir = process.env.HEADLESSCODE_DATA_DIR\n\tprocess.env.HEADLESSCODE_DATA_DIR = storeRoot\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws) // ZERO permissions config\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `rm -rf ${storeRoot}`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, true, \"a store-targeting recursive delete must be refused (isError)\")\n\t\tassert.match(result.content, /central store/, \"refusal message names the central store\")\n\t\t// The refusal happens BEFORE spawn — nothing was executed or deleted.\n\t\tassert.equal(await exists(marker), true, \"the store's content must survive (refused before spawn)\")\n\t\tassert.equal(await exists(storeRoot), true, \"the store dir must survive\")\n\t} finally {\n\t\tif (savedDataDir === undefined) {\n\t\t\tdelete process.env.HEADLESSCODE_DATA_DIR\n\t\t} else {\n\t\t\tprocess.env.HEADLESSCODE_DATA_DIR = savedDataDir\n\t\t}\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t\tawait fs.rm(storeBase, { recursive: true, force: true })\n\t}\n}\n\nasync function testStoreProtectionNotOverridableByPermissions(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-store-nover-\")\n\tconst storeBase = await mkTmpWorkspace(\"hc-ec-store-nover-data-\")\n\tconst storeRoot = path.join(storeBase, \"central-store\")\n\tawait fs.mkdir(storeRoot, { recursive: true })\n\tconst marker = path.join(storeRoot, \"marker.txt\")\n\tawait fs.writeFile(marker, \"keep-me\")\n\tconst savedDataDir = process.env.HEADLESSCODE_DATA_DIR\n\tprocess.env.HEADLESSCODE_DATA_DIR = storeRoot\n\ttry {\n\t\t// An allow-everything permissions config: the store protection is not\n\t\t// configurable, so the command must STILL be refused.\n\t\tconst executor = createHeadlessExecutor(ws, {\n\t\t\tpermissions: {\n\t\t\t\tallowedCommands: [\"rm\", \"rm -rf\", \"*\"],\n\t\t\t\tdeniedCommands: [],\n\t\t\t\tprotectedFiles: [],\n\t\t\t\tallowProtectedWrites: true,\n\t\t\t},\n\t\t})\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `rm -rf ${storeRoot}`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, true, \"store protection is NOT overridable by an allow-everything config\")\n\t\tassert.match(result.content, /central store/, \"refusal message names the central store\")\n\t\tassert.equal(await exists(marker), true, \"nothing was executed or deleted\")\n\t} finally {\n\t\tif (savedDataDir === undefined) {\n\t\t\tdelete process.env.HEADLESSCODE_DATA_DIR\n\t\t} else {\n\t\t\tprocess.env.HEADLESSCODE_DATA_DIR = savedDataDir\n\t\t}\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t\tawait fs.rm(storeBase, { recursive: true, force: true })\n\t}\n}\n\nasync function testWorkspaceScratchCleanupStillAllowed(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-store-cleanup-\")\n\tconst storeBase = await mkTmpWorkspace(\"hc-ec-store-cleanup-data-\")\n\tconst storeRoot = path.join(storeBase, \"central-store\")\n\tconst savedDataDir = process.env.HEADLESSCODE_DATA_DIR\n\tprocess.env.HEADLESSCODE_DATA_DIR = storeRoot\n\ttry {\n\t\t// Ordinary workspace cleanup is NOT the store — it must actually RUN.\n\t\tconst scratch = path.join(ws, \"tmp-scratch\")\n\t\tawait fs.mkdir(scratch, { recursive: true })\n\t\tawait fs.writeFile(path.join(scratch, \"file.txt\"), \"scratch\")\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: \"rm -rf ./tmp-scratch\",\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, false, \"workspace cleanup is allowed (not the store)\")\n\t\tassert.equal(await exists(scratch), false, \"the scratch dir was actually removed\")\n\t} finally {\n\t\tif (savedDataDir === undefined) {\n\t\t\tdelete process.env.HEADLESSCODE_DATA_DIR\n\t\t} else {\n\t\t\tprocess.env.HEADLESSCODE_DATA_DIR = savedDataDir\n\t\t}\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t\tawait fs.rm(storeBase, { recursive: true, force: true })\n\t}\n}\n\nasync function testNonDestructiveStoreAccessAllowed(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-store-read-\")\n\tconst storeBase = await mkTmpWorkspace(\"hc-ec-store-read-data-\")\n\tconst storeRoot = path.join(storeBase, \"central-store\")\n\tconst savedDataDir = process.env.HEADLESSCODE_DATA_DIR\n\tprocess.env.HEADLESSCODE_DATA_DIR = storeRoot\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `echo store-root-is ${storeRoot}`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, false, \"reading/referencing the store via echo is allowed\")\n\t\tassert.match(result.content, /store-root-is/, \"command ran normally\")\n\t} finally {\n\t\tif (savedDataDir === undefined) {\n\t\t\tdelete process.env.HEADLESSCODE_DATA_DIR\n\t\t} else {\n\t\t\tprocess.env.HEADLESSCODE_DATA_DIR = savedDataDir\n\t\t}\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t\tawait fs.rm(storeBase, { recursive: true, force: true })\n\t}\n}\n\n// ─── (d2) redirect-escape guard (issue #122) ────────────────────────────────\n\nasync function testOutsideRedirectRefusedBeforeSpawn(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-redir-\")\n\tconst outside = path.join(os.tmpdir(), `hc-ec-redir-outside-${process.pid}`)\n\tawait fs.rm(outside, { recursive: true, force: true })\n\tconst outsideTarget = path.join(outside, \"foo.md\")\n\tconst savedVar = process.env.HC_EC_TEST_OUTDIR\n\tprocess.env.HC_EC_TEST_OUTDIR = os.tmpdir()\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws) // ZERO permissions config\n\t\t// The classic review-session scratch write — must be refused BEFORE\n\t\t// spawn, so nothing is written and the command never runs.\n\t\tconst denied = [\n\t\t\t`cat > /tmp/foo.md`,\n\t\t\t`echo hi 2> /tmp/err.log`,\n\t\t\t`echo hi > ${outsideTarget}`,\n\t\t\t`echo hi > $HC_EC_TEST_OUTDIR/x.txt`,\n\t\t\t`cat > /tmp/x && echo should-not-run`, // compound: escaping part blocks the chain\n\t\t]\n\t\tfor (const cmd of denied) {\n\t\t\tconst result = await executor.execute(\"execute_command\", { command: cmd, timeout: 10 })\n\t\t\tassert.equal(result.isError, true, `command '${cmd}' must be refused`)\n\t\t\tassert.match(result.content, /outside the workspace/, `refusal must name the boundary, got: ${result.content}`)\n\t\t\tassert.match(result.content, /redirects output/, `refusal must say \"redirects output\", got: ${result.content}`)\n\t\t}\n\t\t// Nothing was written anywhere (the refusal happens before spawn).\n\t\tassert.equal(await exists(path.join(ws, \"foo.md\")), false, \"workspace foo.md must not exist\")\n\t\tassert.equal(await exists(path.join(ws, \"x\")), false, \"workspace x must not exist\")\n\t\tassert.equal(await exists(outsideTarget), false, \"outside target must not exist\")\n\t\tassert.equal(await exists(path.join(os.tmpdir(), \"x.txt\")), false, \"env-var target must not exist\")\n\n\t\t// A redirect INSIDE the workspace still runs and writes.\n\t\tconst inside = await executor.execute(\"execute_command\", {\n\t\t\tcommand: \"echo hello > out.txt\",\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(inside.isError, false, \"an inside-workspace redirect must run\")\n\t\tassert.equal(await fs.readFile(path.join(ws, \"out.txt\"), \"utf-8\"), \"hello\\n\", \"the file must actually be written\")\n\n\t\t// write_to_file to /tmp STILL throws PathTraversalError (unchanged).\n\t\tconst wtf = await executor.execute(\"write_to_file\", { path: \"/tmp/foo.md\", content: \"x\" })\n\t\tassert.equal(wtf.isError, true, \"write_to_file to /tmp must still fail\")\n\t\tassert.match(wtf.content, /escapes the workspace/, `write_to_file refusal must name the boundary, got: ${wtf.content}`)\n\t} finally {\n\t\tif (savedVar === undefined) {\n\t\t\tdelete process.env.HC_EC_TEST_OUTDIR\n\t\t} else {\n\t\t\tprocess.env.HC_EC_TEST_OUTDIR = savedVar\n\t\t}\n\t\tawait fs.rm(outside, { recursive: true, force: true })\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n/**\n * CI safety net for issue #35's fix: `BASH_PATH` must resolve to a REAL\n * bash binary on whatever machine runs this test, not silently fall back to\n * `undefined`. If a future environment (CI image, Docker base image swap)\n * drops bash, this test fails LOUDLY here instead of the failure mode\n * quietly reappearing as a mysterious false test/QA failure somewhere else\n * (which is exactly how #35 itself was discovered — indirectly, via a false\n * QA_VERDICT: FAIL, not a direct signal).\n */\nasync function testBashPathResolvesToARealBinary(): Promise<void> {\n\tassert.notEqual(\n\t\tBASH_PATH,\n\t\tundefined,\n\t\t\"bash must be installed in this environment — execute_command's shell-compatibility fix (issue #35) \" +\n\t\t\t\"depends on it; see the loud module-load warning in executor.ts if this ever legitimately changes\",\n\t)\n\tassert.ok(await exists(BASH_PATH as string), `BASH_PATH (${BASH_PATH}) must point to a file that actually exists`)\n}\n\n/**\n * Issue caught live 2026-08-05: `spawn(cmd, { shell: true })` defaults to\n * `/bin/sh` (dash on Debian/Ubuntu), which has no bash-only features. A\n * model reaching for `${PIPESTATUS[0]}` (common, and nothing in any mode's\n * rules files warns against it) got a shell PARSE error on the WHOLE\n * command line — including a real, passing command that preceded it —\n * misreporting a genuine pass as a failure. This produced a false\n * \"QA_VERDICT: FAIL\" on an otherwise-clean round. Fixed by pointing the\n * spawn's shell at bash explicitly when present.\n */\nasync function testBashOnlySyntaxDoesNotFalselyFailTheCommand(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-bashism-\")\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `echo real-output; echo \"EXIT=\\${PIPESTATUS[0]}\"`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, false, \"a bash-only construct must not falsely fail the whole command\")\n\t\tassert.match(result.content, /real-output/, \"the real command's output must still be captured\")\n\t\tassert.match(result.content, /EXIT=0/, \"PIPESTATUS must actually resolve (proves bash, not sh, ran it)\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (i) oversized stdout is bounded at the cap while the pipe keeps draining ─\n\nasync function testOversizedOutputIsBoundedAtCap(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-ec-cap-\")\n\tconst savedSumm = process.env.HEADLESSCODE_LOCAL_SUMMARIZATION\n\tdelete process.env.HEADLESSCODE_LOCAL_SUMMARIZATION // pin blunt truncation (the default)\n\ttry {\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\t// ~200k chars of stdout — several times MAX_RESULT_CHARS. This also\n\t\t// exceeds the OS pipe buffer, so a handler that stopped draining the\n\t\t// pipe would deadlock the child until the 30s timeout fires.\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `node -e 'process.stdout.write(\"x\".repeat(200000))'`,\n\t\t\ttimeout: 30,\n\t\t})\n\n\t\tassert.equal(result.isError, false, \"a big-output command that finishes must be a normal result\")\n\t\tassert.doesNotMatch(result.content, /timed out/, \"the pipe must be drained so the command completes, not hang\")\n\t\tassert.ok(result.content.length < 200_000, `output must be bounded well below the raw 200k (got ${result.content.length})`)\n\t\tassert.ok(result.content.length > MAX_RESULT_CHARS, \"result still exceeds the cap (cap + trailer)\")\n\t\tassert.match(result.content, /output truncated at \\d+ chars to keep context bounded/, \"blunt truncation trailer present (summarization off)\")\n\t} finally {\n\t\tif (savedSumm === undefined) {\n\t\t\tdelete process.env.HEADLESSCODE_LOCAL_SUMMARIZATION\n\t\t} else {\n\t\t\tprocess.env.HEADLESSCODE_LOCAL_SUMMARIZATION = savedSumm\n\t\t}\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"execute_command: command finishes within timeout -> normal non-error result with full output\", testNormalCompletionWithinTimeout],\n\t[\"execute_command: timeout -> non-error result, partial output, process keeps running and completes on its own\", testTimeoutKeepsProcessAliveAndWritesMarker],\n\t[\"execute_command: rm -rf of the central store is refused BEFORE spawn (zero config)\", testRecursiveDeleteOfCentralStoreRefusedBeforeSpawn],\n\t[\"execute_command: store protection is NOT overridable by an allow-everything permissions config\", testStoreProtectionNotOverridableByPermissions],\n\t[\"execute_command: rm -rf of workspace scratch still runs (not the store)\", testWorkspaceScratchCleanupStillAllowed],\n\t[\"execute_command: non-destructive store access (echo) is allowed\", testNonDestructiveStoreAccessAllowed],\n\t[\"execute_command: outside-workspace redirect (/tmp, $VAR, compound) refused before spawn; inside redirect runs\", testOutsideRedirectRefusedBeforeSpawn],\n\t[\"execute_command: bash-only syntax (${PIPESTATUS[0]}) does not falsely fail the command\", testBashOnlySyntaxDoesNotFalselyFailTheCommand],\n\t[\"execute_command: BASH_PATH resolves to a real binary (CI safety net for issue #35)\", testBashPathResolvesToARealBinary],\n\t[\"execute_command: oversized stdout bounded at the cap, pipe drains, truncation trailer present\", testOversizedOutputIsBoundedAtCap],\n]\n\nasync function main(): Promise<void> {\n\tlet failed = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t}\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} execute_command timeout tests passed`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"},{"path":"src/tools/__tests__/path-safety.test.ts","source":"/**\n * Unit tests for the symlink-escape layer of the path-safety guard\n * (src/tools/executor.ts — resolveWithinWorkspace / SymlinkEscapeError,\n * issue #64).\n *\n * The lexical `../` containment check has long been covered by the other\n * suites' traversal tests; this file targets the NEW second layer: every\n * `fsp` call in the file tools follows symlinks, so a path that stays inside\n * the workspace lexically but resolves outside it through a symlink must be\n * refused for reads AND writes (including the protected-files bypass — a\n * symlink to ~/.ssh would otherwise let an agent write to id_rsa behind the\n * pattern guard).\n *\n * Plain assert-based script (no test framework), run via\n * `npm test` -> `tsx src/tools/__tests__/path-safety.test.ts`.\n */\n\nimport assert from \"node:assert/strict\"\nimport * as fs from \"node:fs/promises\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\n\nimport {\n\tcreateHeadlessExecutor,\n\tcreateLocalExploreExecutor,\n\tresolveWithinWorkspace,\n\tSymlinkEscapeError,\n\tPathTraversalError,\n} from \"../executor.js\"\n\nasync function mkTmpWorkspace(prefix: string): Promise<string> {\n\treturn fs.mkdtemp(path.join(os.tmpdir(), prefix))\n}\n\n/** Create a directory OUTSIDE the workspace with a sentinel file in it. */\nasync function mkOutsideDir(ws: string, prefix: string): Promise<{ outside: string; secret: string }> {\n\tconst outside = await fs.mkdtemp(path.join(os.tmpdir(), prefix))\n\tconst secret = path.join(outside, \"secret.txt\")\n\tawait fs.writeFile(secret, \"top secret\\n\", \"utf-8\")\n\treturn { outside, secret }\n}\n\nasync function exists(p: string): Promise<boolean> {\n\ttry {\n\t\tawait fs.access(p)\n\t\treturn true\n\t} catch {\n\t\treturn false\n\t}\n}\n\n// ─── (a) read through an escaping symlink is refused ─────────────────────────\n\nasync function testReadThroughEscapingSymlinkRefused(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-read-\")\n\ttry {\n\t\tconst { secret } = await mkOutsideDir(ws, \"hc-symlink-outside-\")\n\t\tawait fs.symlink(path.dirname(secret), path.join(ws, \"escape\"))\n\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"read_file\", { path: \"escape/secret.txt\" })\n\t\tassert.equal(result.isError, true, \"reading through an escaping symlink must be refused\")\n\t\tassert.match(result.content, /symlink/i, `must name symlink as the reason, got: ${result.content}`)\n\t\tassert.match(result.content, /[Ee]scapes the workspace/, `must mention the boundary, got: ${result.content}`)\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (b) write through an escaping symlink is refused (protected-file bypass) ─\n\nasync function testWriteThroughEscapingSymlinkRefused(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-write-\")\n\ttry {\n\t\tconst outside = await fs.mkdtemp(path.join(os.tmpdir(), \"hc-symlink-outside-\"))\n\t\ttry {\n\t\t\t// A symlink DIRECTLY to a protected file: lexically `link` (no match\n\t\t\t// against `*.key`/`.env`), but writing through it would clobber\n\t\t\t// outside/id_rsa — the pattern guard would never see it.\n\t\t\tawait fs.writeFile(path.join(outside, \"id_rsa\"), \"original key\\n\", \"utf-8\")\n\t\t\tawait fs.symlink(path.join(outside, \"id_rsa\"), path.join(ws, \"link\"))\n\n\t\t\tconst executor = createHeadlessExecutor(ws)\n\t\t\tconst result = await executor.execute(\"write_to_file\", { path: \"link\", content: \"pwned\" })\n\t\t\tassert.equal(result.isError, true, \"writing through an escaping symlink must be refused\")\n\t\t\tassert.match(result.content, /symlink/i, `must name symlink as the reason, got: ${result.content}`)\n\n\t\t\t// The outside file must be untouched.\n\t\t\tconst untouched = await fs.readFile(path.join(outside, \"id_rsa\"), \"utf-8\")\n\t\t\tassert.equal(untouched, \"original key\\n\", \"the outside file must not have been written\")\n\t\t} finally {\n\t\t\tawait fs.rm(outside, { recursive: true, force: true })\n\t\t}\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (c) every file tool goes through the guard ──────────────────────────────\n\nasync function testAllFileToolsRefuseEscapingSymlink(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-tools-\")\n\ttry {\n\t\tconst { outside, secret } = await mkOutsideDir(ws, \"hc-symlink-outside-\")\n\t\tawait fs.writeFile(path.join(ws, \"target.txt\"), \"hello\\n\", \"utf-8\")\n\t\tawait fs.symlink(path.dirname(secret), path.join(ws, \"escape\"))\n\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst cases: Array<[string, Record<string, unknown>]> = [\n\t\t\t[\"read_file\", { path: \"escape/secret.txt\" }],\n\t\t\t[\"apply_diff\", { path: \"escape/secret.txt\", diff: \"irrelevant\" }],\n\t\t\t[\"search_replace\", { file_path: \"escape/secret.txt\", old_string: \"x\", new_string: \"y\" }],\n\t\t\t[\"edit_file\", { file_path: \"escape/secret.txt\", old_string: \"x\", new_string: \"y\" }],\n\t\t\t[\"list_files\", { path: \"escape\" }],\n\t\t\t[\"describe_image\", { path: \"escape/secret.txt\" }],\n\t\t]\n\t\tfor (const [name, args] of cases) {\n\t\t\tconst result = await executor.execute(name, args)\n\t\t\tassert.equal(result.isError, true, `${name} through an escaping symlink must be refused`)\n\t\t\tassert.match(result.content, /symlink/i, `${name} must name symlink as the reason, got: ${result.content}`)\n\t\t}\n\n\t\t// execute_command's `cwd` resolves through the same guard.\n\t\tconst cwdResult = await executor.execute(\"execute_command\", { command: \"pwd\", cwd: \"escape\" })\n\t\tassert.equal(cwdResult.isError, true, \"execute_command cwd through an escaping symlink must be refused\")\n\t\tassert.match(cwdResult.content, /symlink/i, `cwd refusal must name symlink, got: ${cwdResult.content}`)\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (c2) execute_command redirects are subject to the same boundary (issue #122) ─\n\nasync function testExecuteCommandRedirectsRefuseOutsideWorkspace(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-redir-\")\n\ttry {\n\t\tconst { outside, secret } = await mkOutsideDir(ws, \"hc-symlink-outside-\")\n\t\t// A redirect target outside the workspace — the exact class of scratch\n\t\t// write (e.g. `cat > /tmp/foo.md`) that previously slipped through the\n\t\t// command-string allow/deny gate while every file tool refused it.\n\t\tconst outsideTarget = path.join(outside, \"leak.txt\")\n\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `echo hi > ${outsideTarget}`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(result.isError, true, \"an execute_command redirect outside the workspace must be refused\")\n\t\tassert.match(result.content, /outside the workspace/, `must name the boundary, got: ${result.content}`)\n\t\t// The refusal happens BEFORE spawn — nothing was written.\n\t\tassert.equal(await exists(outsideTarget), false, \"the outside file must not have been created\")\n\t\tassert.equal(await exists(secret), true, \"the outside dir's sentinel must survive untouched\")\n\n\t\t// The same redirect INSIDE the workspace runs fine.\n\t\tconst ok = await executor.execute(\"execute_command\", {\n\t\t\tcommand: `echo hi > leak.txt`,\n\t\t\ttimeout: 10,\n\t\t})\n\t\tassert.equal(ok.isError, false, \"an inside-workspace redirect must run\")\n\t\tassert.equal(await fs.readFile(path.join(ws, \"leak.txt\"), \"utf-8\"), \"hi\\n\", \"the inside file must be written\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (d) read-only executors (reviewer/QA/local explore) get the same guard ──\n\nasync function testReadOnlyExecutorsRefuseEscapingSymlink(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-readonly-\")\n\ttry {\n\t\tconst { outside, secret } = await mkOutsideDir(ws, \"hc-symlink-outside-\")\n\t\tawait fs.symlink(path.dirname(secret), path.join(ws, \"escape\"))\n\n\t\tconst explore = createLocalExploreExecutor(ws)\n\t\tconst result = await explore.execute(\"read_file\", { path: \"escape/secret.txt\" })\n\t\tassert.equal(result.isError, true, \"local-explore read through an escaping symlink must be refused\")\n\t\tassert.match(result.content, /symlink/i, `must name symlink, got: ${result.content}`)\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (e) symlinks that STAY inside the workspace keep working ────────────────\n\nasync function testInternalSymlinkStillAllowed(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-internal-\")\n\ttry {\n\t\tawait fs.mkdir(path.join(ws, \"real\"), { recursive: true })\n\t\tawait fs.writeFile(path.join(ws, \"real\", \"data.txt\"), \"inside\\n\", \"utf-8\")\n\t\tawait fs.symlink(path.join(ws, \"real\"), path.join(ws, \"alias\"))\n\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst read = await executor.execute(\"read_file\", { path: \"alias/data.txt\" })\n\t\tassert.equal(read.isError, false, \"an internal symlink must keep working\")\n\t\tassert.match(read.content, /inside/, \"content must come from the internal target\")\n\n\t\tconst write = await executor.execute(\"write_to_file\", { path: \"alias/new.txt\", content: \"created\\n\" })\n\t\tassert.equal(write.isError, false, \"writing through an internal symlink must keep working\")\n\t\tassert.equal(await fs.readFile(path.join(ws, \"real\", \"new.txt\"), \"utf-8\"), \"created\\n\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (f) dangling symlink whose DESTINATION is outside is refused ────────────\n\nasync function testDanglingEscapingSymlinkRefused(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-dangling-\")\n\ttry {\n\t\tconst outside = await fs.mkdtemp(path.join(os.tmpdir(), \"hc-symlink-outside-\"))\n\t\ttry {\n\t\t\t// Points at a not-yet-existing path OUTSIDE the workspace: a write\n\t\t\t// through it would create that file outside.\n\t\t\tawait fs.symlink(path.join(outside, \"new.txt\"), path.join(ws, \"dangling\"))\n\n\t\t\tconst executor = createHeadlessExecutor(ws)\n\t\t\tconst result = await executor.execute(\"write_to_file\", { path: \"dangling\", content: \"escape\\n\" })\n\t\t\tassert.equal(result.isError, true, \"writing through a dangling escaping symlink must be refused\")\n\t\t\tassert.match(result.content, /symlink/i, `must name symlink, got: ${result.content}`)\n\t\t} finally {\n\t\t\tawait fs.rm(outside, { recursive: true, force: true })\n\t\t}\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (g) a dangling symlink INSIDE the workspace stays writable ──────────────\n\nasync function testDanglingInternalSymlinkWritable(): Promise<void> {\n\tconst ws = await mkTmpWorkspace(\"hc-symlink-dangling-internal-\")\n\ttry {\n\t\tawait fs.symlink(path.join(ws, \"not-yet.txt\"), path.join(ws, \"dangling\"))\n\n\t\tconst executor = createHeadlessExecutor(ws)\n\t\tconst result = await executor.execute(\"write_to_file\", { path: \"dangling\", content: \"created\\n\" })\n\t\tassert.equal(result.isError, false, \"writing through a dangling INTERNAL symlink must keep working\")\n\t\tassert.equal(await fs.readFile(path.join(ws, \"not-yet.txt\"), \"utf-8\"), \"created\\n\")\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── (h) unit-level: error types and messages ────────────────────────────────\n\nasync function testUnitErrorTypes(): Promise<void> {\n\t// Prefix deliberately free of the word \"symlink\": the error messages embed\n\t// the workspace path, and the lexical-traversal assertion below checks the\n\t// message has no symlink wording — a prefix containing it would false-hit.\n\tconst ws = await mkTmpWorkspace(\"hc-pathunit-\")\n\ttry {\n\t\tconst { outside, secret } = await mkOutsideDir(ws, \"hc-symlink-outside-\")\n\t\tawait fs.symlink(path.dirname(secret), path.join(ws, \"escape\"))\n\n\t\t// Escaping symlink -> SymlinkEscapeError (a PathTraversalError).\n\t\tassert.throws(\n\t\t\t() => resolveWithinWorkspace(ws, \"escape/secret.txt\"),\n\t\t\t(err) => {\n\t\t\t\tassert.ok(err instanceof SymlinkEscapeError, \"escaping symlink must throw SymlinkEscapeError\")\n\t\t\t\tassert.ok(err instanceof PathTraversalError, \"SymlinkEscapeError must extend PathTraversalError\")\n\t\t\t\tassert.match(err.message, /symlink/i, \"message names symlink\")\n\t\t\t\tassert.match(err.message, /secret\\.txt/, \"message names the requested path\")\n\t\t\t\treturn true\n\t\t\t},\n\t\t)\n\n\t\t// Plain lexical traversal still throws the base class with its\n\t\t// original message (no symlink involved).\n\t\tassert.throws(\n\t\t\t() => resolveWithinWorkspace(ws, \"../outside\"),\n\t\t\t(err) => {\n\t\t\t\tassert.ok(err instanceof PathTraversalError, \"lexical traversal must throw PathTraversalError\")\n\t\t\t\tassert.ok(!(err instanceof SymlinkEscapeError), \"lexical traversal must NOT be a symlink error\")\n\t\t\t\tassert.doesNotMatch(err.message, /symlink/i, \"plain traversal message has no symlink wording\")\n\t\t\t\treturn true\n\t\t\t},\n\t\t)\n\n\t\t// The escaping symlink ITSELF is refused too — its real location is\n\t\t// outside, so even listing it (`list_files` on \"escape\") must not\n\t\t// reach the outside directory.\n\t\tassert.throws(\n\t\t\t() => resolveWithinWorkspace(ws, \"escape\"),\n\t\t\t(err) => err instanceof SymlinkEscapeError,\n\t\t\t\"the escaping symlink path itself must be refused\",\n\t\t)\n\n\t\t// The root itself and genuinely internal paths resolve fine.\n\t\tassert.equal(resolveWithinWorkspace(ws, \".\"), ws)\n\t\tassert.equal(resolveWithinWorkspace(ws, \"escape\" + \"/..\"), ws)\n\t} finally {\n\t\tawait fs.rm(ws, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"read through an escaping symlink is refused\", testReadThroughEscapingSymlinkRefused],\n\t[\"write through an escaping symlink is refused (protected-file bypass)\", testWriteThroughEscapingSymlinkRefused],\n\t[\"every file tool refuses an escaping symlink (read/write/list/describe/cwd)\", testAllFileToolsRefuseEscapingSymlink],\n\t[\"execute_command redirects outside the workspace are refused before spawn; inside redirects run\", testExecuteCommandRedirectsRefuseOutsideWorkspace],\n\t[\"read-only executors get the same symlink guard\", testReadOnlyExecutorsRefuseEscapingSymlink],\n\t[\"symlinks that stay inside the workspace keep working\", testInternalSymlinkStillAllowed],\n\t[\"dangling symlink escaping the workspace is refused\", testDanglingEscapingSymlinkRefused],\n\t[\"dangling symlink inside the workspace stays writable\", testDanglingInternalSymlinkWritable],\n\t[\"unit: SymlinkEscapeError vs PathTraversalError\", testUnitErrorTypes],\n]\n\nasync function main(): Promise<void> {\n\tlet failed = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t}\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`path-safety: ${failed} of ${tests.length} tests failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`All ${tests.length} tests passed`)\n}\n\nawait main()"}]
